## Code Example
```javascript
function onDeviceInference(text, model) {
  const lang = detectLanguage(text);
  const category = classifier(lang).predict(text);
  const slots = slotTagger(text);
  const explanation = explain(text, category, slots);
  return { category, slots, explanation };
}
```

